                      {item.isCorrect ? "Correct." : `Correct answers: ${item.correctAnswers}.`}
                    </li>
                  ))}
                </ul>
              ) : null}
            </form>
          </div>
        );
      }

      const root = ReactDOM.createRoot(document.getElementById("main-content"));
      root.render(<QuizApp />);
    </script>
  </body>
