  <body>
    <main class="page" id="main-content"></main>

    <script>
      const quizQuestions = [
        {
          id: "q1",
          title: "Which of these languages are statically typed?",
          helpText: "Select every option that usually checks types before the program runs.",
          options: ["Java", "TypeScript", "Haskell", "Ruby"],
          correctAnswers: ["Java", "TypeScript", "Haskell"],
        },
        {
          id: "q2",
          title: "Which languages are commonly used for systems programming?",
          options: ["C", "Rust", "Go", "JavaScript"],
          correctAnswers: ["C", "Rust", "Go"],
        },
        {
          id: "q3",
          title: "Which of these languages are primarily associated with the JVM?",
          options: ["Java", "Kotlin", "Scala", "Swift"],
          correctAnswers: ["Java", "Kotlin", "Scala"],
        },
      ];

      const state = {
        answers: quizQuestions.reduce((accumulator, question) => {
          accumulator[question.id] = [];
          return accumulator;
        }, {}),
        result: null,
      };

      function QuestionField({ question, selectedAnswers }) {
        const helpTextId = question.helpText ? `${question.id}-help` : undefined;
        const helpTextMarkup = question.helpText
          ? `<p class="help-text" id="${helpTextId}">${question.helpText}</p>`
          : "";

        const choicesMarkup = question.options
          .map((option) => {
            const checkboxId = `${question.id}-${option.toLowerCase().replace(/\s+/g, "-")}`;
            const isChecked = selectedAnswers.includes(option);

            return `
              <label class="choice" for="${checkboxId}">
                <input
                  id="${checkboxId}"
                  type="checkbox"
                  data-question-id="${question.id}"
                  value="${option}"
                  ${isChecked ? "checked" : ""}
                />
                <span>${option}</span>
              </label>
            `;
          })
          .join("");

        return `
          <div class="form-field">
            <fieldset ${helpTextId ? `aria-describedby="${helpTextId}"` : ""}>
              <legend>${question.title}</legend>
              ${helpTextMarkup}
              <div class="choices">${choicesMarkup}</div>
            </fieldset>
          </div>
        `;
      }

      function QuizApp() {
        const questionsMarkup = quizQuestions
          .map((question) =>
            QuestionField({
              question,
              selectedAnswers: state.answers[question.id],
            })
          )
          .join("");

        const resultMarkup = state.result
          ? `
            <div class="result" aria-live="polite">
              Score: ${state.result.score} / ${quizQuestions.length}
            </div>
          `
          : "";

        const feedbackMarkup = state.result
          ? `
            <ul class="feedback-list">
              ${state.result.feedback
                .map(
                  (item) => `
                    <li>
                      <strong>${item.title}</strong>: ${
                        item.isCorrect ? "Correct." : `Correct answers: ${item.correctAnswers}.`
                      }
                    </li>
                  `
                )
                .join("")}
            </ul>
          `
          : "";

        return `
          <div class="quiz-shell">
            <header class="hero">
              <p class="eyebrow">Interactive quiz</p>
              <h1>Computer Languages Challenge</h1>
              <p class="intro">
                Test your knowledge of programming ecosystems with three multi-select questions.
              </p>
            </header>

            <form id="quiz-form">
              ${questionsMarkup}

              <div class="actions">
                <button type="submit">Submit quiz</button>
                ${resultMarkup}
              </div>

              ${feedbackMarkup}
            </form>
          </div>
        `;
      }

      function handleToggle(questionId, option) {
        const existingAnswers = state.answers[questionId];
        const hasOption = existingAnswers.includes(option);

        state.answers[questionId] = hasOption
          ? existingAnswers.filter((answer) => answer !== option)
          : [...existingAnswers, option];

        renderApp();
      }

      function handleSubmit(event) {
        event.preventDefault();

        const feedback = quizQuestions.map((question) => {
          const selected = [...state.answers[question.id]].sort();
          const correct = [...question.correctAnswers].sort();
          const isCorrect =
            selected.length === correct.length &&
            selected.every((answer, index) => answer === correct[index]);

          return {
            id: question.id,
            title: question.title,
            isCorrect,
            correctAnswers: question.correctAnswers.join(", "),
          };
        });

        state.result = {
          score: feedback.filter((item) => item.isCorrect).length,
          feedback,
        };

        renderApp();
      }

      function bindEvents() {
        document.querySelectorAll('input[type="checkbox"]').forEach((input) => {
          input.addEventListener("change", (event) => {
            handleToggle(event.target.dataset.questionId, event.target.value);
          });
        });

        document.getElementById("quiz-form").addEventListener("submit", handleSubmit);
      }

      function renderApp() {
        const root = document.getElementById("main-content");
        root.innerHTML = QuizApp();
        bindEvents();
      }

      renderApp();
    </script>
  </body>
</html>
